package com.hireflow.api.dashboard; import com.hireflow.api.job.*; import com.hireflow.api.application.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/dashboard") public class DashboardController {private final JobRepository jobs; private final ApplicationRepository apps; public DashboardController(JobRepository j,ApplicationRepository a){jobs=j;apps=a;} @GetMapping("/recruiter") public Map<String,Object> recruiter(){return Map.of("jobsPosted",jobs.count(),"applications",apps.count(),"shortlisted",apps.countByStatus("SHORTLISTED"),"interviews",apps.countByStatus("INTERVIEW"),"selected",apps.countByStatus("SELECTED"));} @GetMapping("/analytics") public Map<String,Object> analytics(){return Map.of("jobs",jobs.count(),"applications",apps.count(),"shortlisted",apps.countByStatus("SHORTLISTED"),"selected",apps.countByStatus("SELECTED"));}}